-- All fixtures and entries are rolled back; existing inventory is untouched.
begin;
select set_config('request.jwt.claim.sub',(select user_id::text from public.app_profiles where is_developer and active limit 1),true);
set local role authenticated;
do $$
declare cid text:='qa-receipts-'||gen_random_uuid(); oid uuid:=gen_random_uuid(); target uuid:=gen_random_uuid();
 pid uuid; sid uuid:=gen_random_uuid(); purchase uuid:=gen_random_uuid(); line uuid:=gen_random_uuid(); receipt uuid:=gen_random_uuid();
 oc jsonb; payload jsonb; request jsonb; today text:=(now() at time zone 'America/Mexico_City')::date::text; result jsonb;
begin
 insert into public.clients(id,name) values(cid,cid);
 insert into public.business_clients(business_id,client_id) values('pcp',cid);
 insert into public.suppliers(id,name) values(sid,cid);
 perform public.resolve_order_product('pcp',cid,'QA-CODE',null,jsonb_build_object('sku',cid,'name','QA receiving product','unit','Pieza'));
 select product_id into pid from public.product_client_codes where client_id=cid and code='QA-CODE';
 oc:=jsonb_build_object('item_delivery_version',4,'id',oid,'revision',0,'business_id','pcp','client_id',cid,'number',cid,'status','confirmed','order_date',today,'currency','MXN','tax','0','source',null,'items',jsonb_build_array(jsonb_build_object('id',target,'kind','parts','code','QA-CODE','description','QA','unit','PZA','quantity','6','unit_price','10','discount','0','subitems','[]'::jsonb,'commitment_date',today,'fulfillment','pending','completed_date','')));
 perform public.save_purchase_order(oc);
 payload:=jsonb_build_object('id',purchase,'business_id','pcp','supplier_id',sid,'number',cid,'date',today,'expected_date','','currency','MXN','status','draft','notes','','tax','16','revision',0,'items',jsonb_build_array(jsonb_build_object('id',line,'product_id',pid,'quantity','10','unit_price','10','allocations',jsonb_build_array(jsonb_build_object('item_id',target,'quantity','4')))));
 perform public.save_product_catalog(to_jsonb(p)||jsonb_build_object('client_codes',jsonb_build_array(jsonb_build_object('client_id',cid,'code','QA-CODE')),'supplier_ids',jsonb_build_array(sid)),pid,p.updated_at) from public.products p where p.id=pid;
 perform public.save_supplier_purchase(payload);
 request:=jsonb_build_object('id',receipt,'business_id','pcp','purchase_id',purchase,'date',today,'reference','QA','notes','Partial receipt','items',jsonb_build_array(jsonb_build_object('line_id',line,'item_id',target,'quantity','2'),jsonb_build_object('line_id',line,'item_id',null,'quantity','3')));
 begin perform public.receive_supplier_purchase(request);raise exception 'Draft received';exception when raise_exception then if sqlerrm<>'RECEIPT_PURCHASE' then raise;end if;end;
 perform public.save_supplier_purchase(payload||'{"revision":1,"status":"ordered"}');
 begin perform public.receive_supplier_purchase(request||'{"business_id":"jose"}');raise exception 'Cross company received';exception when raise_exception then if sqlerrm<>'RECEIPT_PURCHASE' then raise;end if;end;
 begin perform public.receive_supplier_purchase(request||'{"date":"2199-01-01"}');raise exception 'Future received';exception when raise_exception then if sqlerrm<>'RECEIPT_DATE' then raise;end if;end;
 begin perform public.receive_supplier_purchase(jsonb_set(request,'{items,0,line_id}',to_jsonb(gen_random_uuid()::text)));raise exception 'Foreign line received';exception when raise_exception then if sqlerrm<>'RECEIPT_DESTINATION' then raise;end if;end;
 perform public.receive_supplier_purchase(request);
 perform public.receive_supplier_purchase(request);
 if (select count(*) from public.warehouse_entries where receipt_id=receipt)<>2 then raise exception 'Idempotency failed';end if;
 if not exists(select 1 from public.warehouse_balances('pcp') where product_id=pid and quantity::numeric=5 and reserved::numeric=2 and available::numeric=3) then raise exception 'Balances incorrect';end if;
 if exists(select 1 from public.warehouse_balances('jose') where product_id=pid) then raise exception 'Cross business inventory';end if;
 result:=public.warehouse_receipt_document('pcp',receipt);
 if jsonb_array_length(result->'items')<>2 or result->>'actor_name' is null then raise exception 'Receipt document invalid';end if;
 if not exists(select 1 from public.activity_log where entity_id=receipt::text and action='warehouse.received') then raise exception 'Missing audit';end if;
 begin perform public.receive_supplier_purchase(request||'{"notes":"Changed"}');raise exception 'Different retry accepted';exception when raise_exception then if sqlerrm<>'RECEIPT_CONFLICT' then raise;end if;end;
 begin perform public.cancel_supplier_purchase(purchase,'pcp',2,'QA');raise exception 'Received purchase cancelled';exception when raise_exception then if sqlerrm<>'PURCHASE_RECEIVED' then raise;end if;end;
 request:=request||jsonb_build_object('id',gen_random_uuid());
 begin perform public.receive_supplier_purchase(jsonb_set(request,'{items,1,quantity}','"4"'));raise exception 'Excess accepted';exception when raise_exception then if sqlerrm<>'RECEIPT_EXCESS' then raise;end if;end;
 if (select count(*) from public.warehouse_receipts where purchase_id=purchase)<>1 then raise exception 'Partial failure leaked receipt';end if;
 perform public.receive_supplier_purchase(request);
 if not exists(select 1 from public.warehouse_balances('pcp') where product_id=pid and quantity::numeric=10 and reserved::numeric=4 and available::numeric=6) then raise exception 'Full balances incorrect';end if;
 if exists(select 1 from jsonb_array_elements(public.warehouse_purchase_options('pcp')) p where p->>'id'=purchase::text) then raise exception 'Fully received offered again';end if;
 if (select fulfillment from public.purchase_order_items where id=target)<>'pending' then raise exception 'Receipt changed customer shipment';end if;
 begin update public.warehouse_entries set quantity=1 where receipt_id=receipt;raise exception 'Entry mutation allowed';exception when insufficient_privilege then null;end;
 begin delete from public.warehouse_receipts where id=receipt;raise exception 'Receipt deletion allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 begin perform public.receive_supplier_purchase(request);raise exception 'Unauthorized write';exception when insufficient_privilege then null;end;
 begin perform public.warehouse_purchase_options('pcp');raise exception 'Unauthorized options';exception when insufficient_privilege then null;end;
 if exists(select 1 from public.warehouse_entries) then raise exception 'RLS leak';end if;
end $$;
rollback;
